#include "menu.h"

/* ------------------------------------------------------------------------- */
/* Pre-parsed syntax metadata (Menu_Init)                                    */
/* ------------------------------------------------------------------------- */
typedef struct {
    uint8_t type;                       /* MenuTokenType */
    char    text[MENU_MAX_TOKEN_TEXT];
} ParsedToken;

typedef struct {
    ParsedToken tokens[MENU_MAX_SYNTAX_TOKENS];
    int         token_count;
    int         min_tokens;
    int         max_tokens;
    int         valid;
} ParsedCommand;

typedef struct {
    int idx[MENU_MAX_COMMANDS];
    int n;
} CandidateSet;

enum { RESOLVE_OK = 0, RESOLVE_AMBIGUOUS, RESOLVE_INVALID };

/* Built-in commands, available in every mode except where noted. */
static int menu_builtin_exit(const MenuCommandContext *ctx);
static int menu_builtin_end(const MenuCommandContext *ctx);
static int menu_builtin_help(const MenuCommandContext *ctx);

static const MenuCommandDef g_builtins[] = {
    { "menu_builtin_exit", MENU_MODE_NONE, "EXIT", "Leave the current mode (up one level)",
      menu_builtin_exit, MENU_MODE_NONE },
    { "menu_builtin_end",  MENU_MODE_NONE, "END",  "Return to privileged exec mode (also Ctrl-Z)",
      menu_builtin_end,  MENU_MODE_NONE },
    { "menu_builtin_help", MENU_MODE_NONE, "HELP", "List the commands of this mode (also ?)",
      menu_builtin_help, MENU_MODE_NONE },
};
#define MENU_BUILTIN_COUNT (sizeof(g_builtins) / sizeof(g_builtins[0]))
#define MENU_BUILTIN_END   1

static MenuIo        g_io;
static int           g_is_initialized;
static MenuMode      g_mode = MENU_MODE_EXEC;
static ParsedCommand g_parsed[MENU_MAX_COMMANDS];
static int           g_def_count;

/* Line editor state. */
static char   g_line[MENU_LINE_MAX + 1u];
static size_t g_len;
static int    g_esc_state;      /* 0 idle, 1 after ESC, 2 after ESC '[' */
static int    g_last_cr;        /* previous character was CR (swallow the LF of CRLF) */
static int    g_hist_nav = -1;  /* -1: editing a new line; else age of the recalled entry */
static char   g_hist[MENU_HISTORY_DEPTH][MENU_LINE_MAX + 1u];
static int    g_hist_count;
static int    g_hist_head;      /* slot the next entry is written to */

/* ------------------------------------------------------------------------- */
/* Character and string helpers (no C library)                               */
/* ------------------------------------------------------------------------- */

/**
 * @brief Lower-case one ASCII character.
 * @param c Character code.
 * @return c in lower case when it is 'A'..'Z', otherwise c unchanged.
 */
static int mc_tolower(int c)
{
    return (c >= 'A' && c <= 'Z') ? (c - 'A' + 'a') : c;
}

/**
 * @brief Length of a NUL-terminated string.
 * @param s String (not NULL).
 * @return Number of characters before the NUL.
 */
static size_t mc_strlen(const char *s)
{
    size_t n = 0;
    while (s[n] != '\0') {
        n++;
    }
    return n;
}

/**
 * @brief Case-insensitive equality of two strings.
 * @param a First string.
 * @param b Second string.
 * @return 1 when equal ignoring ASCII case, else 0.
 */
static int mc_strieq(const char *a, const char *b)
{
    while (*a != '\0' && *b != '\0') {
        if (mc_tolower((unsigned char)*a) != mc_tolower((unsigned char)*b)) {
            return 0;
        }
        a++;
        b++;
    }
    return (*a == '\0' && *b == '\0') ? 1 : 0;
}

/**
 * @brief Test whether `prefix` is a non-empty case-insensitive prefix of `word`.
 * @param prefix Typed (possibly abbreviated) token.
 * @param word   Full keyword.
 * @return 1 when prefix matches the start of word, else 0.
 */
static int mc_prefix_nocase(const char *prefix, const char *word)
{
    if (*prefix == '\0') {
        return 0;
    }
    while (*prefix != '\0') {
        if (*word == '\0' || mc_tolower((unsigned char)*prefix) != mc_tolower((unsigned char)*word)) {
            return 0;
        }
        prefix++;
        word++;
    }
    return 1;
}

/**
 * @brief Bounded string copy that always terminates the destination.
 * @param dst Destination buffer.
 * @param cap Destination capacity in bytes (> 0).
 * @param src Source string.
 * @return Number of characters copied (excluding the NUL).
 */
static size_t mc_copy(char *dst, size_t cap, const char *src)
{
    size_t n = 0;
    while (src[n] != '\0' && n + 1u < cap) {
        dst[n] = src[n];
        n++;
    }
    dst[n] = '\0';
    return n;
}

/**
 * @brief Whitespace test for the tokenizer.
 * @param c Character.
 * @return 1 for space or tab, else 0.
 */
static int mc_isspace(int c)
{
    return (c == ' ' || c == '\t') ? 1 : 0;
}

/**
 * @brief Write a NUL-terminated string through the output hook.
 * @param s String to write; ignored when the engine has no output hook.
 * @return None.
 */
void Menu_Write(const char *s)
{
    if (g_io.write != NULL && s != NULL) {
        g_io.write(s, mc_strlen(s));
    }
}

/**
 * @brief Write n spaces (alignment padding).
 * @param n Number of spaces.
 * @return None.
 */
static void menu_pad(size_t n)
{
    while (n-- > 0u) {
        Menu_Write(" ");
    }
}

/* ------------------------------------------------------------------------- */
/* Command table access                                                      */
/* ------------------------------------------------------------------------- */

/**
 * @brief Command definition by unified index (table entries, then built-ins).
 * @param i Index in [0, g_def_count).
 * @return Pointer to the definition.
 */
static const MenuCommandDef *menu_def(int i)
{
    if ((size_t)i < g_menu_command_count) {
        return &g_menu_commands[i];
    }
    return &g_builtins[(size_t)i - g_menu_command_count];
}

/**
 * @brief Mode table entry of a mode.
 * @param mode Mode value.
 * @return Pointer to its MenuModeDef, or NULL when the table lacks it.
 */
static const MenuModeDef *menu_mode_def(MenuMode mode)
{
    for (size_t i = 0; i < g_menu_mode_count; i++) {
        if (g_menu_modes[i].mode == mode) {
            return &g_menu_modes[i];
        }
    }
    return NULL;
}

/**
 * @brief Whether a mode is the configuration mode or one of its sub-modes.
 * @param mode Mode to test.
 * @return 1 when `end` applies (configuration tree), else 0.
 * Walks the parent chain; bounded by MENU_MODE_COUNT steps.
 */
static int menu_is_config_mode(MenuMode mode)
{
    MenuMode m = mode;
    for (unsigned step = 0; step < (unsigned)MENU_MODE_COUNT; step++) {
        const MenuModeDef *md;
        if (m == MENU_MODE_CONFIG) {
            return 1;
        }
        md = menu_mode_def(m);
        if (md == NULL || md->parent == MENU_MODE_NONE) {
            return 0;
        }
        m = md->parent;
    }
    return 0;
}

/**
 * @brief Whether definition i can be typed in a mode.
 * @param i    Unified definition index.
 * @param mode Current mode.
 * @return 1 when available. Exec commands are also available in privileged
 *         mode; `end` in privileged mode (no effect) and the configuration
 *         tree; other built-ins always.
 */
static int menu_def_in_mode(int i, MenuMode mode)
{
    const MenuCommandDef *d = menu_def(i);
    if ((size_t)i >= g_menu_command_count) {
        if ((size_t)i - g_menu_command_count == MENU_BUILTIN_END) {
            return (mode == MENU_MODE_PRIV || menu_is_config_mode(mode)) ? 1 : 0;
        }
        return 1;
    }
    if (d->mode == mode) {
        return 1;
    }
    return (mode == MENU_MODE_PRIV && d->mode == MENU_MODE_EXEC) ? 1 : 0;
}

/* ------------------------------------------------------------------------- */
/* Initialization                                                            */
/* ------------------------------------------------------------------------- */

/**
 * @brief Pre-parse one syntax string into keyword / parameter tokens.
 * @param syntax Syntax text, e.g. "DEBUG WRITE [ADDR] [VALUE]".
 * @param pc     Output metadata; pc->valid is 0 when the syntax breaks a
 *               rule (too many tokens, token too long, required parameter
 *               after an optional one, empty).
 * @return None.
 */
static void menu_parse_syntax(const char *syntax, ParsedCommand *pc)
{
    int  seen_optional = 0;
    size_t pos = 0;

    pc->token_count = 0;
    pc->min_tokens  = 0;
    pc->max_tokens  = 0;
    pc->valid       = 1;

    while (syntax[pos] != '\0') {
        size_t start;
        size_t len;
        ParsedToken *t;

        while (mc_isspace((unsigned char)syntax[pos])) {
            pos++;
        }
        if (syntax[pos] == '\0') {
            break;
        }
        start = pos;
        while (syntax[pos] != '\0' && !mc_isspace((unsigned char)syntax[pos])) {
            pos++;
        }
        len = pos - start;
        if (pc->token_count >= (int)MENU_MAX_SYNTAX_TOKENS || len >= MENU_MAX_TOKEN_TEXT) {
            pc->valid = 0;
            return;
        }
        t = &pc->tokens[pc->token_count];
        for (size_t k = 0; k < len; k++) {
            t->text[k] = syntax[start + k];
        }
        t->text[len] = '\0';
        if (t->text[0] == '[') {
            t->type = (uint8_t)MENU_TOKEN_REQUIRED_PARAM;
            if (seen_optional) {
                pc->valid = 0;
            }
            pc->min_tokens++;
        } else if (t->text[0] == '{') {
            t->type = (uint8_t)MENU_TOKEN_OPTIONAL_PARAM;
            seen_optional = 1;
        } else {
            t->type = (uint8_t)MENU_TOKEN_KEYWORD;
            if (seen_optional) {
                pc->valid = 0;
            }
            pc->min_tokens++;
        }
        pc->token_count++;
    }
    pc->max_tokens = pc->token_count;
    if (pc->token_count == 0) {
        pc->valid = 0;
    }
}

/**
 * @brief Initialize the engine: set the output hook and pre-parse every
 *        command syntax (generated table plus built-ins).
 * @param io Output hook (copied); may be NULL to keep the previous hook.
 * @return 0 on success; -1 when the table exceeds MENU_MAX_COMMANDS or a
 *         syntax is invalid (that entry is then never matched).
 * Side effects: resets the mode to user exec and clears the line editor.
 */
int Menu_Init(const MenuIo *io)
{
    int rc = 0;

    if (io != NULL) {
        g_io = *io;
    }
    g_def_count = (int)(g_menu_command_count + MENU_BUILTIN_COUNT);
    if (g_def_count > (int)MENU_MAX_COMMANDS) {
        g_def_count = (int)MENU_MAX_COMMANDS;
        rc = -1;
    }
    for (int i = 0; i < g_def_count; i++) {
        menu_parse_syntax(menu_def(i)->syntax, &g_parsed[i]);
        if (!g_parsed[i].valid) {
            rc = -1;
        }
    }
    g_mode       = MENU_MODE_EXEC;
    g_len        = 0;
    g_esc_state  = 0;
    g_last_cr    = 0;
    g_hist_nav   = -1;
    g_is_initialized = 1;
    return rc;
}

/* ------------------------------------------------------------------------- */
/* Modes                                                                     */
/* ------------------------------------------------------------------------- */

/**
 * @brief Change the current mode.
 * @param mode New mode; values outside the mode set are ignored.
 * @return None.
 */
void Menu_SetMode(MenuMode mode)
{
    if ((unsigned)mode < MENU_MODE_COUNT) {
        g_mode = mode;
    }
}

/**
 * @brief Current mode.
 * @return The mode commands are matched against.
 */
MenuMode Menu_GetMode(void)
{
    return g_mode;
}

/**
 * @brief Name of a mode as written in the command file.
 * @param mode Mode value.
 * @return "exec", "priv", "config", ... or "?" for an unknown mode.
 */
const char *Menu_ModeName(MenuMode mode)
{
    const MenuModeDef *md = menu_mode_def(mode);
    return (md != NULL) ? md->name : "?";
}

/**
 * @brief Print the prompt of the current mode (no newline).
 * @return None.
 */
void Menu_PrintPrompt(void)
{
    const MenuModeDef *md = menu_mode_def(g_mode);
    Menu_Write((md != NULL) ? md->prompt : "rtlnet?");
}

/**
 * @brief Print the prompt and the line typed so far (after an asynchronous
 *        message such as a link event).
 * @return None.
 */
void Menu_Redisplay(void)
{
    Menu_PrintPrompt();
    g_line[g_len] = '\0';
    Menu_Write(g_line);
}

/**
 * @brief Built-in EXIT: leave the current mode for its parent.
 * @param ctx Callback context (unused).
 * @return 0; at the root mode prints a note and stays.
 */
static int menu_builtin_exit(const MenuCommandContext *ctx)
{
    const MenuModeDef *md = menu_mode_def(g_mode);
    (void)ctx;
    if (md == NULL || md->parent == MENU_MODE_NONE) {
        Menu_Write("% Already at the top level\n");
        return 0;
    }
    g_mode = md->parent;
    return 0;
}

/**
 * @brief Built-in END: return from any configuration mode to privileged exec.
 * @param ctx Callback context (unused).
 * @return 0.
 */
static int menu_builtin_end(const MenuCommandContext *ctx)
{
    (void)ctx;
    g_mode = MENU_MODE_PRIV;
    return 0;
}

/**
 * @brief Built-in HELP: same listing as '?' on an empty line.
 * @param ctx Callback context (unused).
 * @return 0.
 */
static int menu_builtin_help(const MenuCommandContext *ctx)
{
    (void)ctx;
    Menu_PrintHelp();
    return 0;
}

/* ------------------------------------------------------------------------- */
/* Help output                                                               */
/* ------------------------------------------------------------------------- */

/**
 * @brief Render a definition's syntax for display: keywords lower case,
 *        parameters as written.
 * @param i   Unified definition index.
 * @param buf Output buffer.
 * @param cap Buffer capacity.
 * @return Length of the rendered text.
 */
static size_t menu_render_syntax(int i, char *buf, size_t cap)
{
    const ParsedCommand *pc = &g_parsed[i];
    size_t n = 0;
    for (int t = 0; t < pc->token_count; t++) {
        const char *s = pc->tokens[t].text;
        if (t > 0 && n + 1u < cap) {
            buf[n++] = ' ';
        }
        while (*s != '\0' && n + 1u < cap) {
            buf[n++] = (pc->tokens[t].type == MENU_TOKEN_KEYWORD) ? (char)mc_tolower((unsigned char)*s) : *s;
            s++;
        }
    }
    buf[n] = '\0';
    return n;
}

/**
 * @brief List every command available in the current mode, aligned on one
 *        " - " separator column computed from the longest syntax.
 * @return None. HELP and '?' (empty line) both call this.
 */
void Menu_PrintHelp(void)
{
    char   text[MENU_LINE_MAX + 1u];
    size_t width = 0;
    const MenuModeDef *md;

    if (!g_is_initialized) {
        (void)Menu_Init(NULL);
    }
    for (int i = 0; i < g_def_count; i++) {
        if (g_parsed[i].valid && menu_def_in_mode(i, g_mode)) {
            size_t n = menu_render_syntax(i, text, sizeof(text));
            if (n > width) {
                width = n;
            }
        }
    }
    md = menu_mode_def(g_mode);
    Menu_Write((md != NULL) ? md->description : "Commands");
    Menu_Write(" commands:\n");
    for (int i = 0; i < g_def_count; i++) {
        if (g_parsed[i].valid && menu_def_in_mode(i, g_mode)) {
            size_t n = menu_render_syntax(i, text, sizeof(text));
            Menu_Write("  ");
            Menu_Write(text);
            menu_pad(width - n);
            Menu_Write(" - ");
            Menu_Write(menu_def(i)->description);
            Menu_Write("\n");
        }
    }
}

/* ------------------------------------------------------------------------- */
/* Tokenizer and resolver                                                    */
/* ------------------------------------------------------------------------- */

/**
 * @brief Split a writable line into whitespace-separated tokens, in place.
 * @param buf    Line buffer (modified: separators become NUL).
 * @param tokens Output token pointers.
 * @param max    Capacity of tokens.
 * @return Token count, or -1 when the line has more than max tokens.
 */
static int menu_tokenize(char *buf, char *tokens[], int max)
{
    int n = 0;
    char *p = buf;
    while (*p != '\0') {
        while (mc_isspace((unsigned char)*p)) {
            *p++ = '\0';
        }
        if (*p == '\0') {
            break;
        }
        if (n >= max) {
            return -1;
        }
        tokens[n++] = p;
        while (*p != '\0' && !mc_isspace((unsigned char)*p)) {
            p++;
        }
    }
    return n;
}

/**
 * @brief Resolve typed tokens against the commands of the current mode.
 * @param tok      Typed tokens.
 * @param ntok     Number of tokens to resolve.
 * @param cs       Out: surviving candidates (definition indices).
 * @param expanded Out: tokens with keywords written out in full (pointers
 *                 into the parsed table) and parameter values as typed.
 * @param err_pos  Out: index of the offending token on failure.
 * @return RESOLVE_OK, RESOLVE_AMBIGUOUS (several keywords share the typed
 *         prefix) or RESOLVE_INVALID (nothing accepts the token).
 * Rule per position: an exact keyword match wins; else one keyword that the
 * token abbreviates; else any parameter slot. Candidates whose syntax ends
 * before the position drop out.
 */
static int menu_resolve(char *const tok[], int ntok, CandidateSet *cs, const char *expanded[], int *err_pos)
{
    cs->n = 0;
    for (int i = 0; i < g_def_count; i++) {
        if (g_parsed[i].valid && menu_def_in_mode(i, g_mode)) {
            cs->idx[cs->n++] = i;
        }
    }
    for (int p = 0; p < ntok; p++) {
        const char *exact = NULL;
        const char *prefix_kw = NULL;
        int prefix_distinct = 0;
        int has_param = 0;
        int keep = 0;

        for (int c = 0; c < cs->n; c++) {
            const ParsedCommand *pc = &g_parsed[cs->idx[c]];
            const ParsedToken *t;
            if (p >= pc->token_count) {
                continue;
            }
            t = &pc->tokens[p];
            if (t->type != MENU_TOKEN_KEYWORD) {
                has_param = 1;
            } else if (mc_strieq(tok[p], t->text)) {
                exact = t->text;
            } else if (mc_prefix_nocase(tok[p], t->text)) {
                if (prefix_kw == NULL) {
                    prefix_kw = t->text;
                    prefix_distinct = 1;
                } else if (!mc_strieq(prefix_kw, t->text)) {
                    prefix_distinct++;
                }
            }
        }
        if (exact == NULL && prefix_distinct == 1) {
            exact = prefix_kw;
        }
        if (exact == NULL && prefix_distinct > 1) {
            *err_pos = p;
            return RESOLVE_AMBIGUOUS;
        }
        if (exact == NULL && !has_param) {
            *err_pos = p;
            return RESOLVE_INVALID;
        }
        for (int c = 0; c < cs->n; c++) {
            const ParsedCommand *pc = &g_parsed[cs->idx[c]];
            int ok;
            if (p >= pc->token_count) {
                continue;
            }
            if (exact != NULL) {
                ok = (pc->tokens[p].type == MENU_TOKEN_KEYWORD) && mc_strieq(exact, pc->tokens[p].text);
            } else {
                ok = (pc->tokens[p].type != MENU_TOKEN_KEYWORD);
            }
            if (ok) {
                cs->idx[keep++] = cs->idx[c];
            }
        }
        cs->n = keep;
        expanded[p] = (exact != NULL) ? exact : tok[p];
    }
    return RESOLVE_OK;
}

/**
 * @brief Print a resolver error with a caret under the offending token.
 * @param tok     Typed tokens.
 * @param ntok    Token count.
 * @param err_pos Offending token index.
 * @param kind    RESOLVE_AMBIGUOUS or RESOLVE_INVALID.
 * @return None.
 */
static void menu_print_resolve_error(char *const tok[], int ntok, int err_pos, int kind)
{
    size_t col = 2;
    Menu_Write("  ");
    for (int i = 0; i < ntok; i++) {
        if (i > 0) {
            Menu_Write(" ");
        }
        if (i < err_pos) {
            col += mc_strlen(tok[i]) + 1u;
        }
        Menu_Write(tok[i]);
    }
    Menu_Write("\n");
    menu_pad(col);
    Menu_Write("^\n");
    if (kind == RESOLVE_AMBIGUOUS) {
        Menu_Write("% Ambiguous command: \"");
        Menu_Write(tok[err_pos]);
        Menu_Write("\"\n");
    } else {
        Menu_Write("% Invalid input detected at '^' marker.\n");
    }
}

/* ------------------------------------------------------------------------- */
/* Matching and dispatch                                                     */
/* ------------------------------------------------------------------------- */

/**
 * @brief Match one definition against resolved tokens and dispatch it.
 * @param idx       Unified definition index.
 * @param tokens    Expanded tokens (menu_resolve).
 * @param ntok      Token count.
 * @param matched   Out: set to 1 only after the token count is within
 *                  [min_tokens, max_tokens], every keyword matches exactly
 *                  (case-insensitive) at its position, every required
 *                  parameter is present and the definition has an action.
 * @return The callback's return code when matched; -1 otherwise.
 * Side effects: a matched mode-entry command whose callback returns 0 (or
 * that has none) switches to its mode.
 */
static int menu_match_and_dispatch(int idx, const char *const tokens[], int ntok, int *matched)
{
    const MenuCommandDef *d  = menu_def(idx);
    const ParsedCommand  *pc = &g_parsed[idx];
    MenuCommandContext ctx;
    int rc;

    *matched = 0;
    if (!pc->valid) {
        return -1;
    }
    if (ntok < pc->min_tokens || ntok > pc->max_tokens) {
        return -1;
    }
    ctx.argc = 0;
    ctx.mode = g_mode;
    for (int i = 0; i < ntok; i++) {
        if (pc->tokens[i].type == MENU_TOKEN_KEYWORD) {
            if (!mc_strieq(tokens[i], pc->tokens[i].text)) {
                return -1;
            }
        } else {
            if (ctx.argc >= (int)MENU_MAX_ARGS) {
                return -1;
            }
            ctx.argv[ctx.argc++] = tokens[i];
        }
    }
    for (int i = ctx.argc; i < (int)MENU_MAX_ARGS; i++) {
        ctx.argv[i] = NULL;
    }
    if (d->callback == NULL && d->enter_mode == MENU_MODE_NONE) {
        return -1;
    }
    *matched = 1;
    rc = (d->callback != NULL) ? d->callback(&ctx) : 0;
    if (rc == 0 && d->enter_mode != MENU_MODE_NONE) {
        Menu_SetMode(d->enter_mode);
    }
    return rc;
}

/* ------------------------------------------------------------------------- */
/* Context help                                                              */
/* ------------------------------------------------------------------------- */

typedef struct {
    char        label[MENU_MAX_TOKEN_TEXT + 2u];
    const char *description;
} HelpEntry;

/**
 * @brief Help text for a keyword at a position shared by several commands.
 * @param expanded Resolved keywords before the position.
 * @param k        Position.
 * @param keyword  Keyword at the position.
 * @return KEYWORD directive text for that path in this mode, or NULL.
 */
static const char *menu_keyword_help(const char *const expanded[], int k, const char *keyword)
{
    for (size_t i = 0; i < g_menu_keyword_count; i++) {
        const MenuKeywordDef *kd = &g_menu_keywords[i];
        char path[MENU_LINE_MAX + 1u];
        char *pt[MENU_MAX_TOKENS];
        int n;
        int ok;
        if (!(kd->mode == g_mode || (g_mode == MENU_MODE_PRIV && kd->mode == MENU_MODE_EXEC))) {
            continue;
        }
        (void)mc_copy(path, sizeof(path), kd->path);
        n = menu_tokenize(path, pt, (int)MENU_MAX_TOKENS);
        if (n != k + 1) {
            continue;
        }
        ok = mc_strieq(pt[k], keyword);
        for (int j = 0; j < k && ok; j++) {
            ok = mc_strieq(pt[j], expanded[j]);
        }
        if (ok) {
            return kd->description;
        }
    }
    return NULL;
}

/**
 * @brief Add one help entry unless its label is already listed.
 * @param list  Entry array.
 * @param count In/out number of entries.
 * @param cap   Capacity.
 * @param label Label text.
 * @param lower 1 to lower-case the label (keywords).
 * @param desc  Description.
 * @return Index of the (new or existing) entry, or -1 when full.
 */
static int menu_help_add(HelpEntry *list, int *count, int cap, const char *label, int lower, const char *desc)
{
    char tmp[MENU_MAX_TOKEN_TEXT + 2u];
    size_t n = mc_copy(tmp, sizeof(tmp), label);
    if (lower) {
        for (size_t i = 0; i < n; i++) {
            tmp[i] = (char)mc_tolower((unsigned char)tmp[i]);
        }
    }
    for (int i = 0; i < *count; i++) {
        if (mc_strieq(list[i].label, tmp)) {
            return i;
        }
    }
    if (*count >= cap) {
        return -1;
    }
    (void)mc_copy(list[*count].label, sizeof(list[*count].label), tmp);
    list[*count].description = desc;
    return (*count)++;
}

/**
 * @brief Context-sensitive help for a partly typed line ('?' after text).
 * @param text Line typed so far. Ending in whitespace: list the keywords and
 *             parameters that may follow, plus <cr> when the line is already
 *             a complete command. Ending in a partial word: list the keywords
 *             it can complete to.
 * @return None.
 */
static void menu_context_help(const char *text)
{
    char  buf[MENU_LINE_MAX + 1u];
    char *tok[MENU_MAX_TOKENS];
    const char *expanded[MENU_MAX_TOKENS];
    CandidateSet cs;
    HelpEntry list[MENU_MAX_COMMANDS];
    int count = 0;
    int n;
    int k;
    int partial;
    int err_pos = 0;
    int rr = RESOLVE_OK;
    size_t len = mc_copy(buf, sizeof(buf), text);
    size_t width = 0;

    partial = (len > 0u && !mc_isspace((unsigned char)buf[len - 1u])) ? 1 : 0;
    n = menu_tokenize(buf, tok, (int)MENU_MAX_TOKENS);
    if (n < 0) {
        Menu_Write("% Too many tokens\n");
        return;
    }
    k = partial ? (n - 1) : n;
    rr = menu_resolve(tok, k, &cs, expanded, &err_pos);
    if (rr != RESOLVE_OK) {
        menu_print_resolve_error(tok, n, err_pos, rr);
        return;
    }
    for (int c = 0; c < cs.n; c++) {
        const ParsedCommand *pc = &g_parsed[cs.idx[c]];
        const MenuCommandDef *d = menu_def(cs.idx[c]);
        if (k < pc->token_count) {
            const ParsedToken *t = &pc->tokens[k];
            if (t->type == MENU_TOKEN_KEYWORD) {
                if (!partial || mc_prefix_nocase(tok[k], t->text)) {
                    int shared = 0;
                    const char *desc;
                    for (int o = 0; o < cs.n; o++) {
                        const ParsedCommand *po = &g_parsed[cs.idx[o]];
                        if (o != c && k < po->token_count && po->tokens[k].type == MENU_TOKEN_KEYWORD &&
                            mc_strieq(po->tokens[k].text, t->text)) {
                            shared = 1;
                        }
                    }
                    desc = shared ? menu_keyword_help(expanded, k, t->text) : d->description;
                    (void)menu_help_add(list, &count, (int)MENU_MAX_COMMANDS, t->text, 1,
                                        (desc != NULL) ? desc : "Further keywords follow");
                }
            } else if (!partial) {
                char label[MENU_MAX_TOKEN_TEXT + 2u];
                size_t ln = mc_copy(label + 1, sizeof(label) - 2u, t->text + 1);
                label[0] = '<';
                if (ln > 0u) {
                    label[ln] = '>';   /* replaces the closing ']' or '}' */
                }
                (void)menu_help_add(list, &count, (int)MENU_MAX_COMMANDS, label, 0, d->description);
            }
        }
        if (!partial && k >= pc->min_tokens && k <= pc->max_tokens) {
            (void)menu_help_add(list, &count, (int)MENU_MAX_COMMANDS, "<cr>", 0, d->description);
        }
    }
    if (count == 0) {
        Menu_Write(partial ? "% Unrecognized command\n" : "% No further keywords\n");
        return;
    }
    for (int i = 0; i < count; i++) {
        size_t w = mc_strlen(list[i].label);
        if (w > width) {
            width = w;
        }
    }
    for (int i = 0; i < count; i++) {
        Menu_Write("  ");
        Menu_Write(list[i].label);
        menu_pad(width - mc_strlen(list[i].label));
        Menu_Write(" - ");
        Menu_Write(list[i].description);
        Menu_Write("\n");
    }
}

/* ------------------------------------------------------------------------- */
/* History                                                                   */
/* ------------------------------------------------------------------------- */

/**
 * @brief History entry by age (0 = most recent).
 * @param age Age in [0, g_hist_count).
 * @return Pointer to the stored line.
 */
static const char *menu_hist_get(int age)
{
    int slot = (g_hist_head - 1 - age + (int)MENU_HISTORY_DEPTH * 2) % (int)MENU_HISTORY_DEPTH;
    return g_hist[slot];
}

/**
 * @brief Remember a command line unless it repeats the most recent entry.
 * @param line Line to store (truncated to MENU_LINE_MAX).
 * @return None.
 */
static void menu_hist_add(const char *line)
{
    if (g_hist_count > 0 && mc_strieq(menu_hist_get(0), line)) {
        return;
    }
    (void)mc_copy(g_hist[g_hist_head], sizeof(g_hist[0]), line);
    g_hist_head = (g_hist_head + 1) % (int)MENU_HISTORY_DEPTH;
    if (g_hist_count < (int)MENU_HISTORY_DEPTH) {
        g_hist_count++;
    }
}

/* ------------------------------------------------------------------------- */
/* Line processing                                                           */
/* ------------------------------------------------------------------------- */

/**
 * @brief Parse and execute one command line in the current mode.
 * @param line Command text (no line terminator needed). "!!" repeats the
 *             previous line; "?" or HELP lists the mode's commands; a
 *             trailing '?' on a token ("show ?", "sh?") gives context help.
 * @return The callback's return code when a command matched; 0 for an empty
 *         line or help; -1 for NULL, unknown, ambiguous or incomplete input.
 */
int Menu_ProcessLine(const char *line)
{
    char  buf[MENU_LINE_MAX + 1u];
    char *tok[MENU_MAX_TOKENS];
    const char *expanded[MENU_MAX_TOKENS];
    CandidateSet cs;
    int n;
    int err_pos = 0;
    int rr;
    size_t len;

    if (line == NULL) {
        return -1;
    }
    if (!g_is_initialized) {
        (void)Menu_Init(NULL);
    }
    len = mc_copy(buf, sizeof(buf), line);
    while (len > 0u && mc_isspace((unsigned char)buf[len - 1u])) {
        buf[--len] = '\0';
    }
    if (len > 0u && buf[len - 1u] == '?') {
        int blank = 1;
        buf[--len] = '\0';
        for (size_t i = 0; i < len; i++) {
            if (!mc_isspace((unsigned char)buf[i])) {
                blank = 0;
            }
        }
        if (blank) {
            Menu_PrintHelp();
        } else {
            menu_context_help(buf);
        }
        return 0;
    }
    n = menu_tokenize(buf, tok, (int)MENU_MAX_TOKENS);
    if (n == 0) {
        return 0;
    }
    if (n < 0) {
        Menu_Write("% Too many tokens\n");
        return -1;
    }
    if (n == 1 && tok[0][0] == '!' && tok[0][1] == '!' && tok[0][2] == '\0') {
        char again[MENU_LINE_MAX + 1u];
        if (g_hist_count == 0) {
            Menu_Write("% No previous command\n");
            return -1;
        }
        (void)mc_copy(again, sizeof(again), menu_hist_get(0));
        Menu_Write(again);
        Menu_Write("\n");
        return Menu_ProcessLine(again);
    }
    menu_hist_add(line);

    rr = menu_resolve(tok, n, &cs, expanded, &err_pos);
    if (rr != RESOLVE_OK) {
        menu_print_resolve_error(tok, n, err_pos, rr);
        return -1;
    }
    for (int c = 0; c < cs.n; c++) {
        int matched = 0;
        int rc = menu_match_and_dispatch(cs.idx[c], expanded, n, &matched);
        if (matched) {
            return rc;
        }
    }
    for (int c = 0; c < cs.n; c++) {
        if (g_parsed[cs.idx[c]].min_tokens > n) {
            Menu_Write("% Incomplete command.\n");
            return -1;
        }
    }
    Menu_Write("% Unknown command or too many parameters.\n");
    return -1;
}

/* ------------------------------------------------------------------------- */
/* Line editor                                                               */
/* ------------------------------------------------------------------------- */

/**
 * @brief Erase the displayed input line (backspace over it).
 * @return None. The buffer length becomes 0.
 */
static void menu_erase_line(void)
{
    while (g_len > 0u) {
        Menu_Write("\b \b");
        g_len--;
    }
}

/**
 * @brief Replace the input line with a history entry and display it.
 * @param age Entry age, or -1 for an empty line.
 * @return None.
 */
static void menu_recall(int age)
{
    menu_erase_line();
    g_line[0] = '\0';
    if (age >= 0) {
        g_len = mc_copy(g_line, sizeof(g_line), menu_hist_get(age));
        Menu_Write(g_line);
    }
    g_hist_nav = age;
}

/**
 * @brief End of line: run the edited line, then print the prompt.
 * @return None. The editor buffer is cleared before the command runs, so a
 *         command may print freely.
 */
static void menu_enter_line(void)
{
    char run[MENU_LINE_MAX + 1u];
    g_line[g_len] = '\0';
    (void)mc_copy(run, sizeof(run), g_line);
    g_len = 0;
    g_hist_nav = -1;
    Menu_Write("\n");
    (void)Menu_ProcessLine(run);
    Menu_PrintPrompt();
}

/**
 * @brief Feed one received character to the line editor.
 * @param c Character code (0..255).
 *   CR or LF (CRLF counted once): execute the line, print the prompt.
 *   '?': context help for the text so far (not stored), then redisplay.
 *   Backspace/DEL: erase one character. Ctrl-U: erase the line.
 *   Ctrl-C: cancel the line. Ctrl-Z: cancel and `end` (configuration modes).
 *   ESC [ A / ESC [ B: previous / next history entry.
 *   Printable ASCII: append and echo (silently dropped past MENU_LINE_MAX).
 * @return None.
 */
void Menu_InputChar(int c)
{
    char echo[2];
    int was_cr = g_last_cr;

    if (!g_is_initialized) {
        (void)Menu_Init(NULL);
    }
    g_last_cr = 0;
    if (g_esc_state == 1) {
        g_esc_state = (c == '[') ? 2 : 0;
        return;
    }
    if (g_esc_state == 2) {
        g_esc_state = 0;
        if (c == 'A' && g_hist_nav + 1 < g_hist_count) {
            menu_recall(g_hist_nav + 1);
        } else if (c == 'B') {
            menu_recall((g_hist_nav > 0) ? (g_hist_nav - 1) : -1);
        }
        return;
    }
    switch (c) {
    case 0x1B:
        g_esc_state = 1;
        break;
    case '\n':
        if (!was_cr) {
            menu_enter_line();
        }
        break;
    case '\r':
        g_last_cr = 1;
        menu_enter_line();
        break;
    case 0x03:
        Menu_Write("^C\n");
        g_len = 0;
        g_hist_nav = -1;
        Menu_PrintPrompt();
        break;
    case 0x1A:
        Menu_Write("^Z\n");
        g_len = 0;
        g_hist_nav = -1;
        if (menu_is_config_mode(g_mode)) {
            g_mode = MENU_MODE_PRIV;
        }
        Menu_PrintPrompt();
        break;
    case 0x08:
    case 0x7F:
        if (g_len > 0u) {
            g_len--;
            Menu_Write("\b \b");
        }
        break;
    case 0x15:
        menu_erase_line();
        break;
    case '?': {
        int blank = 1;
        g_line[g_len] = '\0';
        for (size_t i = 0; i < g_len; i++) {
            if (!mc_isspace((unsigned char)g_line[i])) {
                blank = 0;
            }
        }
        Menu_Write("?\n");
        if (blank) {
            Menu_PrintHelp();
        } else {
            menu_context_help(g_line);
        }
        Menu_PrintPrompt();
        Menu_Write(g_line);
        break;
    }
    default:
        if (c >= 0x20 && c <= 0x7E && g_len < MENU_LINE_MAX) {
            g_line[g_len++] = (char)c;
            echo[0] = (char)c;
            echo[1] = '\0';
            Menu_Write(echo);
        }
        break;
    }
}
